export async function listLiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Issue[]> {
  const db = getDb();
  const rows = db
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(issues.number)
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

/**
 * Copies the given source issues into a project as a fresh start: numbered
 * from 1 in the given order, in `status`, unassigned and unstarted, authored
 * by `authorId`. Labels come along; comments, attachments and links do not.
 */
export async function insertClonedIssues(
  orgId: OrgId,
  toProjectId: ProjectId,
  source: readonly Issue[],
  status: IssueStatus,
  authorId: UserId,
): Promise<number> {
  const db = getDb();
  const stamp = toIsoTimestamp(new Date());
  let number = 0;
  for (const issue of source) {
    number += 1;
    const id = newId();
    db.insert(issues)
      .values({
        id,
        orgId,
        projectId: toProjectId,
        number,
        title: issue.title,
        description: issue.description,
        status,
        priority: issue.priority,
        authorId,
        assigneeId: null,
        parentId: null,
        estimate: issue.estimate,
        dueAt: issue.dueAt,
        startedAt: null,
        completedAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    if (issue.labelIds.length > 0) {
      db.insert(issueLabels)
        .values(
          issue.labelIds.map((labelId) => ({ orgId, issueId: id, labelId })),
        )
        .run();
    }
  }
  return source.length;
}

